1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.validation.IdentityKeyNormalizer;
12	
13	import java.time.LocalDate;
14	import java.time.Period;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
31	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    Owner toOwner(OwnerDto ownerDto);
38	
39	    /**
40	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
41	     */
42	    default String displayName(Owner owner) {
43	        if (owner == null) {
44	            return null;
45	        }
46	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
47	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
48	        return lastName + ", " + firstName;
49	    }
50	
51	    /**
52	     * Returns the upper-cased first letters of firstName and lastName,
53	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
54	     */
55	    default String initials(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        StringBuilder sb = new StringBuilder();
60	        String firstName = owner.getFirstName();
61	        String lastName = owner.getLastName();
62	        if (firstName != null && !firstName.isEmpty()) {
63	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
64	        }
65	        if (lastName != null && !lastName.isEmpty()) {
66	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
67	        }
68	        return sb.toString();
69	    }
70	
71	    /**
72	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
73	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
74	     * Returns {@code null} unless both the customer code and registration date are present.
75	     */
76	    default String membershipNumber(Owner owner) {
77	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
78	            return null;
79	        }
80	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
81	        return owner.getCustomerCode() + "-M" + yy;
82	    }
83	
84	    /**
85	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
86	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
87	     */
88	    default Integer checkDigit(Owner owner) {
89	        if (owner == null || owner.getCustomerCode() == null) {
90	            return null;
91	        }
92	        String code = owner.getCustomerCode();
93	        int sum = 0;
94	        boolean dbl = true;
95	        for (int i = code.length() - 1; i >= 0; i--) {
96	            char c = code.charAt(i);
97	            if (c < '0' || c > '9') {
98	                continue;
99	            }
100	            int d = c - '0';
101	            if (dbl) {
102	                d *= 2;
103	                if (d > 9) {
104	                    d -= 9;
105	                }
106	            }
107	            sum += d;
108	            dbl = !dbl;
109	        }
110	        return (10 - (sum % 10)) % 10;
111	    }
112	
113	    /**
114	     * Returns the owner's numeric membership level. Starts at {@code 1}; adds {@code 1} when an
115	     * email address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is
116	     * 0); capped at {@code 3} (level 4 is reserved for tenure).
117	     */
118	    default Integer membershipLevel(Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        int level = 1;
123	        String email = owner.getEmail();
124	        if (email != null && !email.isEmpty()) {
125	            level++;
126	        }
127	        Integer namesakeCount = owner.getNamesakeCount();
128	        if (namesakeCount != null && namesakeCount == 0) {
129	            level++;
130	        }
131	        return Math.min(level, 3);
132	    }
133	
134	    /**
135	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
136	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
137	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
138	     */
139	    default String locality(Owner owner) {
140	        if (owner == null) {
141	            return null;
142	        }
143	        String code = owner.getCustomerCode();
144	        if (code == null) {
145	            return "UNKNOWN";
146	        }
147	        int dash = code.indexOf('-');
148	        return dash >= 0 ? code.substring(0, dash) : code;
149	    }
150	
151	    /**
152	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
153	     * on its registration day at creation time). A {@code null} stored value is treated as
154	     * {@code false}, so the field is always present in the response.
155	     */
156	    default Boolean bulkSignupWarning(Owner owner) {
157	        if (owner == null) {
158	            return null;
159	        }
160	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
161	    }
162	
163	    /**
164	     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
165	     * duplicate, but sharing an existing owner's last name and postcode with a different telephone.
166	     * A {@code null} stored value is treated as {@code false}, so the field is always present in the
167	     * response.
168	     */
169	    default Boolean possibleDuplicate(Owner owner) {
170	        if (owner == null) {
171	            return null;
172	        }
173	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
174	    }
175	
176	    /**
177	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
178	     * present, otherwise {@code PHONE}.
179	     */
180	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
181	        if (owner == null) {
182	            return null;
183	        }
184	        String email = owner.getEmail();
185	        return (email != null && !email.isEmpty())
186	            ? OwnerDto.ContactPreferenceEnum.EMAIL
187	            : OwnerDto.ContactPreferenceEnum.PHONE;
188	    }
189	
190	    /**
191	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
192	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
193	     */
194	    default String identityKey(Owner owner) {
195	        return IdentityKeyNormalizer.derive(owner);
196	    }
197	
198	    /**
199	     * Derives the owner's {@code ageBand} from {@code birthDate}, measured as of the owner's
200	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
201	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
202	     * no reference registration date is available), so the field is absent from the response.
203	     */
204	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
205	        if (owner == null || owner.getBirthDate() == null) {
206	            return null;
207	        }
208	        LocalDate reference = owner.getRegistrationDate();
209	        if (reference == null) {
210	            reference = LocalDate.now();
211	        }
212	        int age = Period.between(owner.getBirthDate(), reference).getYears();
213	        if (age < 18) {
214	            return OwnerDto.AgeBandEnum.MINOR;
215	        }
216	        if (age < 65) {
217	            return OwnerDto.AgeBandEnum.ADULT;
218	        }
219	        return OwnerDto.AgeBandEnum.SENIOR;
220	    }
221	
222	    @Mapping(target = "id", ignore = true)
223	    @Mapping(target = "pets", ignore = true)
